<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';const props=defineProps<{modelValue?:string|null}>();const emit=defineEmits(['update:modelValue']);const area=ref<HTMLElement|null>(null);const allowed=new Set(['P','BR','STRONG','B','EM','I','U','UL','OL','LI','BLOCKQUOTE','H1','H2','H3','H4']);function clean(value:string){const root=document.createElement('div');root.innerHTML=value;for(const el of Array.from(root.querySelectorAll('*'))){if(['SCRIPT','STYLE','IFRAME','OBJECT'].includes(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...Array.from(el.childNodes));continue;}for(const attr of Array.from(el.attributes))el.removeAttribute(attr.name);}return root.innerHTML;}function update(){if(area.value)emit('update:modelValue',clean(area.value.innerHTML));}function format(command:string){area.value?.focus();document.execCommand(command,false);update();}onMounted(()=>{if(area.value)area.value.innerHTML=clean(props.modelValue||'');});watch(()=>props.modelValue,value=>{if(area.value&&document.activeElement!==area.value)area.value.innerHTML=clean(value||'');});
</script><template><div class="pms-rich-editor"><div class="pms-rich-toolbar"><button type="button" aria-label="Bold" @mousedown.prevent="format('bold')"><b>B</b></button><button type="button" aria-label="Italic" @mousedown.prevent="format('italic')"><i>I</i></button><button type="button" aria-label="Underline" @mousedown.prevent="format('underline')"><u>U</u></button><button type="button" @mousedown.prevent="format('insertUnorderedList')" aria-label="Bulleted list"><i aria-hidden="true" class="ti ti-list"></i></button><button type="button" @mousedown.prevent="format('insertOrderedList')" aria-label="Numbered list"><i aria-hidden="true" class="ti ti-list-numbers"></i></button><button type="button" @mousedown.prevent="format('removeFormat')" aria-label="Clear format"><i aria-hidden="true" class="ti ti-clear-formatting"></i></button></div><div ref="area" contenteditable="true" role="textbox" aria-label="Description editor" aria-multiline="true" class="pms-rich-content" @input="update"></div></div></template>